insert into public.paid_content (content_type, content_id, payload, sort_order) values
('theory', 'kb_001', '{"tagId":"kb_001","originalNumber":1,"title":"初頭効果","summary":"最初に得た情報が、その後の印象や評価の基準として強く残る傾向。第一印象は後から修正しにくいため、関係の入口ほど重要になる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 0),
('theory', 'kb_002', '{"tagId":"kb_002","originalNumber":2,"title":"親近効果","summary":"最後に得た情報ほど記憶や判断に残りやすい傾向。会話や体験は、終わり方によって全体の印象が変わる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 1),
('theory', 'kb_003', '{"tagId":"kb_003","originalNumber":3,"title":"ハロー効果","summary":"目立つ一つの長所や短所が、その人全体の評価にまで広がる傾向。見た目や肩書、最初の成果が他の判断まで左右する。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 2),
('theory', 'kb_004', '{"tagId":"kb_004","originalNumber":4,"title":"単純接触効果","summary":"接する回数が増えるほど、対象への親しみや好意が高まりやすくなる傾向。ただし、もともとの不快感が強い場合には逆効果になりうる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 3),
('theory', 'kb_005', '{"tagId":"kb_005","originalNumber":5,"title":"類似性魅力効果","summary":"価値観、経歴、趣味などの共通点が多い相手ほど、親しみや信頼を感じやすい傾向。共通点は関係を始める足場になる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 4),
('theory', 'kb_006', '{"tagId":"kb_006","originalNumber":6,"title":"相補性","summary":"互いに異なる性質や役割が補い合うことで、関係が安定したり成果が高まったりする考え方。似ていることだけが相性を決めるわけではない。","sourceType":"心理学","discipline":"社会心理学","conceptType":"概念・フレームワーク","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 5),
('theory', 'kb_007', '{"tagId":"kb_007","originalNumber":7,"title":"好意の返報性","summary":"相手から好意を示されると、自分も好意を返したくなりやすい傾向。好意は待つより、先に示すことで循環が生まれる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"概念・フレームワーク","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 6),
('theory', 'kb_008', '{"tagId":"kb_008","originalNumber":8,"title":"自己開示の返報性","summary":"自分の考えや経験を適度に開示すると、相手も同程度の自己開示を返しやすくなる傾向。親密さは一方的ではなく段階的に深まる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"概念・フレームワーク","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 7),
('theory', 'kb_009', '{"tagId":"kb_009","originalNumber":9,"title":"社会的浸透理論","summary":"人間関係は、会話の範囲と深さが少しずつ広がることで親密になるという理論。急激な踏み込みより、相互的な自己開示が重要になる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 8),
('theory', 'kb_010', '{"tagId":"kb_010","originalNumber":10,"title":"不確実性低減理論","summary":"人は初対面の相手について予測できない状態を不快に感じ、質問や観察を通じて不確実性を減らそうとするという理論。安心感は予測可能性から生まれる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 9),
('theory', 'kb_011', '{"tagId":"kb_011","originalNumber":11,"title":"応答性理論","summary":"相手の話や感情に適切に反応することが、信頼や親密さを生むという考え方。理解された感覚は、単なる相づちより内容に即した反応から生まれる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 10),
('theory', 'kb_012', '{"tagId":"kb_012","originalNumber":12,"title":"知覚されたパートナー応答性","summary":"相手が自分を理解し、尊重し、気遣ってくれていると感じる程度。関係の満足度は、実際の行動だけでなく、そう受け取られているかで決まる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"概念・フレームワーク","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 11),
('theory', 'kb_013', '{"tagId":"kb_013","originalNumber":13,"title":"ラポールの三要素モデル","summary":"相互の注意、肯定的な感情、行動の同調がそろうと、自然な信頼関係が生まれるというモデル。会話の内容だけでなく、リズムや雰囲気も重要になる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 12),
('theory', 'kb_014', '{"tagId":"kb_014","originalNumber":14,"title":"ミラーリング効果","summary":"相手の姿勢や表情、動作を自然に同調させると、親近感や一体感が生まれやすくなる傾向。露骨な模倣は不信感を招くため、自然さが必要になる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 13),
('theory', 'kb_015', '{"tagId":"kb_015","originalNumber":15,"title":"言語スタイル同調","summary":"語彙、文の長さ、話す速さなどが似てくるほど、会話の一体感や関係の調和が高まりやすい現象。","sourceType":"心理学","discipline":"社会心理学","conceptType":"概念・フレームワーク","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 14),
('theory', 'kb_016', '{"tagId":"kb_016","originalNumber":16,"title":"呼び名効果","summary":"相手の名前や望む呼び方を適切に使うことで、注意や親近感を引き出しやすくなる実務的な考え方。過剰に繰り返すと不自然になる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":"実務上の通称。学術的な正式名称・効果範囲を要確認。","categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 15),
('theory', 'kb_017', '{"tagId":"kb_017","originalNumber":17,"title":"カクテルパーティー効果","summary":"多くの音や情報の中でも、自分の名前や関心の高い情報には注意が向きやすい現象。人は自分に関係する情報を優先して拾う。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 16),
('theory', 'kb_018', '{"tagId":"kb_018","originalNumber":18,"title":"質問好意効果","summary":"相手に関心を持って質問し、話をよく聞く人は好意的に評価されやすい傾向。質問の量より、答えを受け止めて深めることが重要になる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 17),
('theory', 'kb_019', '{"tagId":"kb_019","originalNumber":19,"title":"ベン・フランクリン効果","summary":"一度誰かを助けると、その行動と整合させるために相手への好意が高まりやすい傾向。小さな依頼が関係形成のきっかけになることがある。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 18),
('theory', 'kb_020', '{"tagId":"kb_020","originalNumber":20,"title":"自己検証理論","summary":"人は肯定的な評価だけでなく、自分が抱く自己像と一致する評価を求めるという理論。相手を理解するには、理想像だけでなく自己認識を見る必要がある。","sourceType":"心理学","discipline":"社会心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 19),
('theory', 'kb_021', '{"tagId":"kb_021","originalNumber":21,"title":"自己拡張理論","summary":"人は関係を通じて、新しい能力、視点、経験を自分の一部として取り込みたいと考えるという理論。成長を感じられる関係は魅力を持ちやすい。","sourceType":"心理学","discipline":"社会心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 20),
('theory', 'kb_022', '{"tagId":"kb_022","originalNumber":22,"title":"対人魅力の報酬理論","summary":"一緒にいることで快い感情や利益を得られる相手ほど、好意を持たれやすいという理論。相手にとっての心理的報酬が関係を支える。","sourceType":"心理学","discipline":"社会心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 21),
('theory', 'kb_023', '{"tagId":"kb_023","originalNumber":23,"title":"感情伝染","summary":"表情、声、態度を通じて、ある人の感情が周囲へ無意識に広がる現象。機嫌や不安は個人の内側だけで完結しない。","sourceType":"心理学","discipline":"社会心理学","conceptType":"概念・フレームワーク","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 22),
('theory', 'kb_024', '{"tagId":"kb_024","originalNumber":24,"title":"アクティブ・コンストラクティブ・レスポンディング","summary":"相手の良い報告に、関心と喜びを示しながら積極的に反応する方法。成功を一緒に喜ぶ反応は、単なる励まし以上に関係を強める。","sourceType":"心理学","discipline":"社会心理学","conceptType":"概念・フレームワーク","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 23),
('theory', 'kb_025', '{"tagId":"kb_025","originalNumber":25,"title":"プラットフォール効果","summary":"高い能力を持つ人が小さな失敗を見せると、親しみやすさが増すことがある現象。能力への信頼がない状態では、失敗はそのまま低評価になりうる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 24),
('theory', 'kb_026', '{"tagId":"kb_026","originalNumber":26,"title":"ゲイン・ロス効果","summary":"一貫して好意的な評価より、否定的な評価から好意的な評価へ変化した方が強く好まれることがある現象。評価の変化幅が感情を強める。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 25),
('theory', 'kb_027', '{"tagId":"kb_027","originalNumber":27,"title":"誤帰属理論","summary":"ある原因で生じた感情や身体反応を、別の対象が原因だと誤って解釈することがあるという理論。","sourceType":"心理学","discipline":"社会心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 26),
('theory', 'kb_028', '{"tagId":"kb_028","originalNumber":28,"title":"吊り橋効果","summary":"恐怖や緊張による高揚を、目の前の相手への魅力だと誤認する可能性を示す現象。強い感情は、その原因を取り違えやすい。","sourceType":"心理学","discipline":"社会心理学","conceptType":"効果・バイアス","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 27),
('theory', 'kb_029', '{"tagId":"kb_029","originalNumber":29,"title":"ピーク・エンドの法則","summary":"体験全体は、最も感情が強かった瞬間と最後の印象によって記憶されやすいという法則。平均的な質だけでなく、山場と終わり方が重要になる。","sourceType":"心理学","discipline":"社会心理学","conceptType":"原理・法則","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の構築"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 28),
('theory', 'kb_030', '{"tagId":"kb_030","originalNumber":30,"title":"社会的交換理論","summary":"人間関係を、得られる報酬と負担の比較から捉える理論。関係は感情だけでなく、互いの利益、コスト、代替可能性にも左右される。","sourceType":"心理学","discipline":"対人関係心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の管理"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 29),
('theory', 'kb_031', '{"tagId":"kb_031","originalNumber":31,"title":"衡平理論","summary":"人は、自分と相手の貢献と見返りの比率が釣り合っているときに公平だと感じるという理論。絶対量より、負担と利益のバランスが問題になる。","sourceType":"心理学","discipline":"対人関係心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の管理"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 30),
('theory', 'kb_032', '{"tagId":"kb_032","originalNumber":32,"title":"コミューナル関係・交換関係","summary":"相手の必要に応じて支え合う関係と、与えたものに相応の返礼を求める関係を区別する考え方。関係の前提を取り違えると不満が生まれる。","sourceType":"心理学","discipline":"対人関係心理学","conceptType":"概念・フレームワーク","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の管理"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 31),
('theory', 'kb_033', '{"tagId":"kb_033","originalNumber":33,"title":"相互依存性理論","summary":"自分の結果が相手の選択に、相手の結果が自分の選択に左右される関係を分析する理論。関係の力学は、依存度と代替選択肢によって変わる。","sourceType":"心理学","discipline":"対人関係心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の管理"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 32),
('theory', 'kb_034', '{"tagId":"kb_034","originalNumber":34,"title":"投資モデル","summary":"関係への満足度、代替関係の魅力、これまでの投資量が、関係を続ける意思を決めるというモデル。","sourceType":"心理学","discipline":"対人関係心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の管理"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 33),
('theory', 'kb_035', '{"tagId":"kb_035","originalNumber":35,"title":"最小関心原理","summary":"関係の継続をより強く望む側ほど、交渉上の力が弱くなりやすいという原理。離れる選択肢を持つ側が主導権を握りやすい。","sourceType":"心理学","discipline":"対人関係心理学","conceptType":"原理・法則","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の管理"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 34),
('theory', 'kb_036', '{"tagId":"kb_036","originalNumber":36,"title":"愛着理論","summary":"幼少期から形成される他者への信頼や不安のパターンが、成人後の親密な関係にも影響するという理論。","sourceType":"心理学","discipline":"対人関係心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の管理"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 35),
('theory', 'kb_037', '{"tagId":"kb_037","originalNumber":37,"title":"親密性平衡モデル","summary":"一方が距離を縮めると、相手が距離を取るなど、人は望ましい親密さを保つよう非言語行動を調整するというモデル。","sourceType":"心理学","discipline":"対人関係心理学","conceptType":"理論・モデル","sourceName":null,"sourceDetail":null,"domains":["対人術","関係の管理"],"principles":[],"relatedIds":[],"reliability":"学術文献要付与","status":"seed","notes":null,"categoryId":"psychology","categoryTitle":"心理学"}'::jsonb, 36),
